$('projectUpload').onchange=async e=>{try{let f=e.target.files[0];if(!f||f.size>60e6)throw Error();let s=JSON.parse(await f.text());if((!names[s.pkg]&&s.pkg!=='custom')||!Array.isArray(s.views)||s.views.length>12||!s.art)throw Error();for(let k of ['w','d','h'])if(!Number.isFinite(s[k])||s[k]<30||s[k]>500)throw Error();if(s.pkg==='custom'){if(typeof s.customSvg!=='string')throw Error();showCustom(sanitizeSvg(s.customSvg),s.customName||'내 전개도')}else await loadPackage(s.pkg);for(const a of Object.values(s.art)){if(typeof a.url!=='string'||!a.url.startsWith('data:image/'))throw Error();a.img=await loadImg(a.url)}Object.assign(state,s);if(s.pkg==='custom')source=state.customSvg=sanitizeSvg(s.customSvg);texture=s.customTexture?await loadImg(s.customTexture):textures[state.mat];syncControls();cache.clear();updateFlat();renderViews();schedule();toast('프로젝트를 불러왔습니다')}catch{toast('올바른 PACKFLOW 프로젝트 파일을 선택해주세요')}};
