function tiff(c,dpi){let ctx=c.getContext('2d'),data=ctx.getImageData(0,0,c.width,c.height).data,n=14,ifd=8,end=ifd+2+n*12+4,bits=end,xres=bits+8,yres=xres+8,offset=yres+8,buf=new ArrayBuffer(offset+data.length),v=new DataView(buf);v.setUint16(0,0x4949,true);v.setUint16(2,42,true);v.setUint32(4,8,true);v.setUint16(ifd,n,true);let entries=[[256,4,1,c.width],[257,4,1,c.height],[258,3,4,bits],[259,3,1,1],[262,3,1,2],[273,4,1,offset],[277,3,1,4],[278,4,1,c.height],[279,4,1,data.length],[282,5,1,xres],[283,5,1,yres],[284,3,1,1],[296,3,1,2],[338,3,1,2]];entries.forEach((e,i)=>{let p=ifd+2+i*12;v.setUint16(p,e[0],true);v.setUint16(p+2,e[1],true);v.setUint32(p+4,e[2],true);e[1]===3&&e[2]===1?v.setUint16(p+8,e[3],true):v.setUint32(p+8,e[3],true)});for(let i=0;i<4;i++)v.setUint16(bits+i*2,8,true);v.setUint32(xres,dpi,true);v.setUint32(xres+4,1,true);v.setUint32(yres,dpi,true);v.setUint32(yres+4,1,true);new Uint8Array(buf,offset).set(data);return new Blob([buf],{type:'image/tiff'})}
