$('export').onclick=async()=>{let type=$('exportType').value,width=Math.min(4096,Math.max(512,+$('exportWidth').value||2048)),dpi=Math.min(600,Math.max(72,+$('dpi').value||300));try{if(type==='json'){download(new Blob([projectJSON()],{type:'application/json'}),'packflow-project.json');return}if(type==='svg'){let svg=$('dieline').querySelector('svg').cloneNode(true);if(!$('includeDesign').checked)svg.querySelectorAll('[data-face]').forEach(el=>el.remove());download(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),'packflow-dieline.svg');return}let c=document.createElement('canvas');c.width=width;if(type==='flatpng'){let svg=$('dieline').querySelector('svg').cloneNode(true),vb=svg.viewBox.baseVal;if(!$('includeDesign').checked)svg.querySelectorAll('[data-face]').forEach(el=>el.remove());c.height=Math.round(width*vb.height/vb.width);svg.setAttribute('width',c.width);svg.setAttribute('height',c.height);let url=URL.createObjectURL(new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}));try{let img=await loadImg(url),ctx=c.getContext('2d');if(!$('transparent').checked){ctx.fillStyle='white';ctx.fillRect(0,0,c.width,c.height)}ctx.drawImage(img,0,0,c.width,c.height)}finally{URL.revokeObjectURL(url)}}else{if(!supported()){toast('이 구조의 3D 내보내기는 준비 중입니다');return}let r=$('stage').getBoundingClientRect();c.height=Math.round(width*r.height/r.width);render(c,$('transparent').checked)}if(type==='tiff')download(tiff(c,dpi),'packflow-mockup.tiff');else{let blob=await new Promise(res=>c.toBlob(res,'image/png'));download(await pngDpi(blob,dpi),type==='flatpng'?'packflow-dieline.png':'packflow-mockup.png')}toast('파일을 내보냈습니다')}catch(e){toast('내보내기에 실패했습니다. 이미지 크기를 줄여 다시 시도해주세요');console.error(e)}};
$('exportTop').onclick=()=>{switchTab('finish');$('settings').scrollTo({top:$('settings').scrollHeight,behavior:'smooth'});$('exportCard').scrollIntoView({behavior:'smooth',block:'nearest'})};$('panelToggle').onclick=()=>{document.querySelector('main').classList.toggle('panelHidden');schedule()};$('expand3').onclick=()=>{document.querySelector('.workspace').classList.toggle('only3');schedule()};$('expand2').onclick=()=>{document.querySelector('.workspace').classList.toggle('only2');schedule()};$('help').onclick=()=>$('info').showModal();$('closeInfo').onclick=()=>$('info').close();new ResizeObserver(schedule).observe($('stage'));
