const oldApplyLayers=applyLayers;
applyLayers=function(){oldApplyLayers();const palette={cut:'#ef3038',fold:'#1260dd',bleed:'#ce21b5',safe:'#039a69'};Object.entries(palette).forEach(([k,c])=>{let g=$('dieline').querySelector('#'+k+'-layer');if(g){g.setAttribute('stroke',c);g.querySelectorAll('line,path,rect,polyline,polygon').forEach(el=>{el.setAttribute('stroke',c);el.setAttribute('stroke-width','1.2');el.setAttribute('vector-effect','non-scaling-stroke');el.setAttribute('fill','none')})}})};
function sanitizeSvg(raw){let doc=new DOMParser().parseFromString(raw,'image/svg+xml');if(doc.querySelector('parsererror')||doc.documentElement.localName!=='svg')throw Error('올바른 SVG 파일이 아닙니다.');const allowed=new Set(['svg','g','path','line','rect','circle','ellipse','polygon','polyline','text','tspan','title','desc']);const attrs=new Set(['id','x','y','x1','y1','x2','y2','width','height','viewBox','cx','cy','r','rx','ry','d','points','transform','fill','stroke','stroke-width','stroke-dasharray','stroke-linecap','stroke-linejoin','fill-rule','font-size','text-anchor','dominant-baseline','opacity','xmlns']);let root=doc.documentElement;for(const el of [...root.querySelectorAll('*')]){if(!allowed.has(el.localName)){el.remove();continue}for(const a of [...el.attributes])if(!attrs.has(a.name)||/url\s*\(|javascript:|data:|https?:/i.test(a.value))el.removeAttribute(a.name)}for(const a of [...root.attributes])if(!attrs.has(a.name)||(a.name!=='xmlns'&&/url\s*\(|javascript:|data:|https?:/i.test(a.value)))root.removeAttribute(a.name);root.setAttribute('xmlns','http://www.w3.org/2000/svg');if(!root.getAttribute('viewBox')){let w=parseFloat(root.getAttribute('width')),h=parseFloat(root.getAttribute('height'));if(!(w>0&&h>0))throw Error('viewBox 또는 가로·세로 크기가 있는 SVG를 선택해주세요.');root.setAttribute('viewBox',`0 0 ${w} ${h}`)}let vb=root.getAttribute('viewBox').trim().split(/[ ,]+/).map(Number);if(vb.length!==4||!vb.every(Number.isFinite)||vb[2]<=0||vb[3]<=0)throw Error('SVG 크기를 확인해주세요.');root.removeAttribute('width');root.removeAttribute('height');return new XMLSerializer().serializeToString(root)}
function dxfToSvg(raw){const lines=raw.replace(/\r/g,'').split('\n'),pairs=[];for(let i=0;i+1<lines.length;i+=2)pairs.push([lines[i].trim(),lines[i+1].trim()]);let entities=[],inEntities=false,current=null;for(let i=0;i<pairs.length;i++){let [code,value]=pairs[i];if(code==='2'&&value==='ENTITIES'){inEntities=true;continue}if(inEntities&&code==='0'){if(current)entities.push(current);current=null;if(value==='ENDSEC'){inEntities=false;continue}current={type:value,pairs:[]}}else if(inEntities&&current)current.pairs.push([code,value])}if(current)entities.push(current);const supportedTypes=['LINE','LWPOLYLINE','TEXT'];if(entities.some(e=>!supportedTypes.includes(e.type)))throw Error('이 DXF에는 지원하지 않는 곡선/객체가 있습니다. SVG로 내보내 업로드해주세요.');let segments=[],texts='';for(const e of entities){const get=k=>e.pairs.find(p=>p[0]===k)?.[1];if(e.type==='TEXT'){let x=Number(get('10')),y=-Number(get('20')),size=Number(get('40'))||4;if(!Number.isFinite(x)||!Number.isFinite(y))throw Error('텍스트 좌표를 읽을 수 없습니다.');let text=(get('1')||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));texts+=`<text x="${x}" y="${y}" font-size="${size}" fill="#666">${text}</text>`;continue}let layer=(get('8')||'CUT').toLowerCase();let kind=/fold|crease|score|오시/.test(layer)?'fold':/bleed/.test(layer)?'bleed':/safe/.test(layer)?'safe':'cut';if(e.type==='LINE')segments.push({kind,p:[[+get('10'),-get('20')],[+get('11'),-get('21')]]});else{if(e.pairs.some(([k,v])=>k==='42'&&Number(v)!==0))throw Error('곡선이 있는 DXF는 SVG로 변환해주세요.');let pts=[];for(let i=0;i<e.pairs.length;i++)if(e.pairs[i][0]==='10'){let y=e.pairs.slice(i+1).find(p=>p[0]==='20');pts.push([+e.pairs[i][1],-Number(y?.[1])])}if(Number(get('70'))&1)pts.push(pts[0]);for(let i=1;i<pts.length;i++)segments.push({kind,p:[pts[i-1],pts[i]]})}}if(!segments.length||segments.some(s=>s.p.flat().some(v=>!Number.isFinite(v))))throw Error('지원되는 LINE / LWPOLYLINE 좌표가 없습니다.');let xs=segments.flatMap(s=>s.p.map(p=>p[0])),ys=segments.flatMap(s=>s.p.map(p=>p[1])),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y;if(!w||!h)throw Error('전개도 크기를 확인해주세요.');let groups=['cut','fold','bleed','safe'].map(k=>`<g id="${k}-layer" fill="none" stroke="black" ${k==='cut'?'':'stroke-dasharray="3 2"'}>${segments.filter(s=>s.kind===k).map(s=>line(...s.p.flat())).join('')}</g>`).join('');return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${x-5} ${y-5} ${w+10} ${h+10}">${groups}<g id="panel-labels-layer">${texts}</g></svg>`}
function showCustom(svg,name){playing=false;$('play').textContent='▷';source=svg;state.pkg='custom';state.customSvg=svg;state.customName=name;state.art={};cache.clear();$('modelName').textContent=name;$('modelSpec').textContent='내 전개도 · 2D 검토';$('unsupported').hidden=false;$('uploadStatus').textContent=name+' · 업로드 완료 (2D)';$('clearDieline').hidden=false;$('sourceDxf').hidden=true;$('package').selectedIndex=-1;$('structureStatus').textContent='내 전개도 · 접힘축 등록 전';['dimW','dimD','dimH','fold','play','foldBtn','unfoldBtn','artUpload','faceSelect','clearArt','clearAllArt'].forEach(k=>$(k).disabled=true);$('dimNote').textContent='사용자 전개도는 치수·3D 연결을 아직 지원하지 않습니다.';flatZoom=1;flatPan=[0,0];flatTransform();updateFlat();schedule()}
$('dielineUpload').onchange=async e=>{let f=e.target.files[0];if(!f)return;try{if(f.size>5*1024*1024)throw Error('5 MB 이하의 파일을 선택해주세요.');let raw=await f.text();if(/\.dxf$/i.test(f.name))raw=dxfToSvg(raw);showCustom(sanitizeSvg(raw),f.name);toast('전개도를 2D 작업 영역에 열었습니다')}catch(err){toast(err.message)}e.target.value=''};
