const reviewGuides={bleed:{title:'재단 여유',concept:'재단선 바깥까지 배경색이나 이미지를 연장한 영역입니다.',reason:'재단 위치에 오차가 생겨도 종이의 흰 테두리가 드러나지 않도록 합니다.',fix:'제작업체가 지정한 여유값만큼 배경을 연장하세요. 현재 표시된 3 mm 전체 경계는 참고용이며, 칼선별 정밀 오프셋이 아닙니다.'},safe:{title:'안전 영역',concept:'중요한 글자·로고를 재단선과 접힘선에서 안쪽으로 떨어뜨려 배치하는 영역입니다.',reason:'재단이나 접힘 오차로 정보가 잘리거나 모서리에 걸리는 문제를 줄입니다.',fix:'중요한 요소를 안전선 안쪽으로 옮기고, 여유값은 제작업체 기준에 맞춰 확인하세요. 표시값은 3 mm입니다.'},seal:{title:'접착 / 실링 영역',concept:'종이를 접착하거나 밀봉하기 위해 확보하는 영역입니다. 이 상자에서는 GLUE 접착 날개를 확인합니다.',reason:'인쇄·코팅이 접착 성능에 영향을 주거나 접착부에서 디자인이 가려질 수 있습니다.',fix:'강조된 접착 날개의 디자인을 비우고, 인쇄·코팅 허용 여부를 업체에 확인하세요. 열접착 포장의 실링 영역은 이 종이상자 모델에 정의되어 있지 않습니다.'},fold:{title:'접힘선',concept:'면과 면이 만나는 접는 축으로, 파란 점선으로 표시됩니다.',reason:'글자나 로고가 접는 축을 가로지르면 왜곡되거나 인쇄가 갈라질 수 있습니다.',fix:'핵심 요소를 접힘선에서 떼어 배치하고 접힘 슬라이더로 3D 상태를 확인하세요.'}};
let currentReview=null;const reviewChecks={};
function showReview(key){currentReview=key;const g=reviewGuides[key];$('reviewDetail').replaceChildren();for(let [label,text] of [['개념',g.concept],['이유',g.reason],['수정법',g.fix]]){let b=document.createElement('b'),p=document.createElement('p');b.textContent=label;p.textContent=text;$('reviewDetail').append(b,p)}$$('[data-review]').forEach(b=>b.classList.toggle('active',b.dataset.review===key));$('reviewChecked').checked=!!reviewChecks[key];updateFlat();if(key==='seal'){if(supported()){selectFace(12);let gl=$('dieline').querySelector('[data-face="12"]');if(gl){gl.querySelectorAll('rect').forEach(r=>r.setAttribute('fill','#ffb60044'))}}else{let p=document.createElement('p');p.textContent='이 전개도에는 접착/실링 영역이 등록되지 않았습니다. 원본 도면의 표기를 확인하세요.';$('reviewDetail').append(p)}}else{const checkbox=document.querySelector(`[data-layer="${key}"]`);if(checkbox)checkbox.checked=true;applyLayers();let group=$('dieline').querySelector('#'+key+'-layer');if(group){group.classList.add('review-highlight');group.querySelectorAll('line,path,rect').forEach(e=>e.setAttribute('stroke-width','2.4'))}else{let p=document.createElement('p');p.textContent='현재 전개도에 이 구조선 레이어가 없습니다. 업로드 파일의 레이어 구분을 확인하세요.';$('reviewDetail').append(p)}}}
$$('[data-review]').forEach(b=>b.onclick=()=>showReview(b.dataset.review));$('reviewChecked').onchange=e=>{if(currentReview)reviewChecks[currentReview]=e.target.checked;else{e.target.checked=false;toast('먼저 검수 항목을 선택해주세요')}};
let reviewEndpoint='';try{reviewEndpoint=localStorage.getItem('packflowReviewEndpoint')||''}catch{}$('reviewEndpoint').value=reviewEndpoint;if(reviewEndpoint)$('apiStatus').textContent='주소 등록 · 미검증';
$('saveEndpoint').onclick=()=>{let val=$('reviewEndpoint').value.trim();try{if(val){let u=new URL(val);if(u.protocol!=='https:'&&!(u.protocol==='http:'&&['localhost','127.0.0.1'].includes(u.hostname)))throw Error();if(u.username||u.password)throw Error()}reviewEndpoint=val;localStorage.setItem('packflowReviewEndpoint',val);$('apiStatus').textContent=val?'주소 등록 · 미검증':'미연결';toast(val?'검수 서버 주소를 저장했습니다':'검수 서버 연결을 해제했습니다')}catch{toast('HTTPS 주소 또는 로컬 서버 주소를 입력해주세요')}};
$('runReview').onclick=async()=>{if(!reviewEndpoint){$('apiResult').textContent='아직 GPT가 연결되지 않았습니다. 검수 서버 주소와 서버 측 API 키·검수 지침 설정이 필요합니다.';return}let btn=$('runReview');btn.disabled=true;$('apiResult').textContent='검수 서버에 요청 중입니다…';try{const c=document.createElement('canvas');c.width=960;c.height=540;render(c);let svg=new XMLSerializer().serializeToString($('dieline').querySelector('svg'));const response=await fetch(reviewEndpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({schemaVersion:1,package:{type:state.pkg,name:state.customName||names[state.pkg],dimensionsMm:{width:state.w,depth:state.d,height:state.h},material:state.mat,finish:state.finish},selectedFace:state.selected,reviewChecks,dielineSvg:svg,previewPng:supported()?c.toDataURL('image/png'):null,artwork:Object.entries(state.art).map(([face,a])=>({face:Number(face),x:a.x,y:a.y,scale:a.scale,rotation:a.rotate}))}),signal:AbortSignal.timeout(60000)});if(!response.ok)throw Error(`서버 응답 ${response.status}`);const data=await response.json();if(typeof data.review!=='string'||!data.review.trim())throw Error('서버의 review 응답이 비어 있습니다');$('apiResult').textContent=data.review;$('apiStatus').textContent='응답 수신'}catch(err){$('apiStatus').textContent='연결 실패';$('apiResult').textContent='검수를 완료하지 못했습니다. 서버 주소·연결 설정을 확인해주세요. '+err.message}finally{btn.disabled=false}};
switchTab('structure');

function faceLabel(id){id=Number(id);if(id<4)return ['BACK · 뒷면','LEFT · 왼쪽','FRONT · 앞면','RIGHT · 오른쪽'][id];if(id===12)return 'GLUE · 접착 날개';return (id<8?'TOP':'BOTTOM')+' · '+['뒤','왼쪽','앞','오른쪽'][(id-4)%4]+' 날개'}
for(let id=4;id<=12;id++){let o=document.createElement('option');o.value=id;o.textContent=faceLabel(id);$('faceSelect').append(o)}

const cloudUrl = 'https://esenhewhmiwdektrsgdy.supabase.co/rest/v1/packflow_projects';
const cloudKey = 'sb_publishable_yJVLDcJ1pvbrMe8BVjlCGg_9bcMWnTX';
let cloudSessionRequest;
async function getCloudSession() {
  const storageKey = 'packflowSupabaseSession';
  const session = JSON.parse(localStorage.getItem(storageKey) || 'null');
  if (session?.expires_at > Date.now() / 1000 + 60) return session;
  if (!cloudSessionRequest) {
    cloudSessionRequest = (async () => {
      const path = session ? 'token?grant_type=refresh_token' : 'signup';
      const response = await fetch(new URL('/auth/v1/' + path, cloudUrl), {
        method: 'POST',
        headers: {apikey: cloudKey, 'Content-Type': 'application/json'},
        body: JSON.stringify(session ? {refresh_token: session.refresh_token} : {})
      });
      const result = await response.json();
      if (!response.ok || !result.access_token) {
        throw Error(result.msg || result.message || 'Supabase 익명 세션을 시작할 수 없습니다');
      }
      result.expires_at = Date.now() / 1000 + result.expires_in;
      localStorage.setItem(storageKey, JSON.stringify(result));
      return result;
    })().finally(() => { cloudSessionRequest = null; });
  }
  return cloudSessionRequest;
}
async function cloudProject(save) {
  let id = localStorage.getItem('packflowCloudId');
  if (!id && save) id = crypto.randomUUID();
  if (!id) return toast('이 브라우저에서 먼저 클라우드에 저장해주세요');
  try {
    const session = await getCloudSession();
    const response = await fetch(save ? cloudUrl : cloudUrl + '?id=eq.' + id + '&select=project', {
      method: save ? 'POST' : 'GET',
      headers: {apikey: cloudKey, Authorization: 'Bearer ' + session.access_token, 'Content-Type': 'application/json', Prefer: 'resolution=merge-duplicates'},
      body: save ? JSON.stringify({id, project: JSON.parse(projectJSON())}) : undefined
    });
    if (!response.ok) {
      const error = await response.json().catch(() => ({}));
      throw Error('Supabase ' + response.status + ' · ' + (error.message || error.code || '저장 요청 실패'));
    }
    if (save) {
      localStorage.setItem('packflowCloudId', id);
      toast('Supabase에 저장했습니다');
    } else {
      const [row] = await response.json();
      if (!row) throw Error('저장된 프로젝트가 없습니다');
      const files = new DataTransfer();
      files.items.add(new File([JSON.stringify(row.project)], 'packflow.json'));
      await $('projectUpload').onchange({target: {files: files.files}});
    }
  } catch (error) { toast(error.message + ' · Supabase 설정을 확인해주세요'); }
}
$('cloudSave').onclick = () => cloudProject(true);
$('cloudLoad').onclick = () => cloudProject(false);
